qry09a_ExtractNoAge <- "
SELECT  id, ENCRYPTED_TRUE_PEN, AGE_AT_GRAD, psi_gender_cleaned, PSI_AWARD_SCHOOL_YEAR, 
PSI_CREDENTIAL_CATEGORY, CREDENTIAL_AWARD_DATE_D, 0 AS LASTCRED, HIGHEST_CRED_BY_DATE
