FROM       MinEnrolment
WHERE      PSI_GENDER <> 'Unknown'
  AND      PSI_GENDER <> ''
  AND      PSI_GENDER <> '(Unspecified)'
  AND      PSI_GENDER IS NOT NULL
  AND      IS_FIRST_ENROLMENT='Yes'
GROUP BY   PSI_GENDER;"
