SET    BGS_Matching_STP_Credential_PEN.Final_Probable_Match = 'Yes', 
       BGS_Matching_STP_Credential_PEN.FINAL_CIP_CODE_4 = [BGS_Matching_STP_Cdtl_Check_MatchInstAwardYearOnly].Final_CIP_CODE_4,
