qry_List_STP_Credential_Non_Dup_Using_BGS_CIPS <- "
SELECT Credential_Non_Dup_BGS_IDs.PSI_CODE, 
       Credential_Non_Dup_BGS_IDs.PSI_PROGRAM_CODE,
       Credential_Non_Dup_BGS_IDs.PSI_CREDENTIAL_PROGRAM_DESCRIPTION,
