          dacso_q009_weight_occs.age_group_rollup,
          LEFT(lcp4_cd, 2),
          dacso_q009_weight_occs.ttrain,
          dacso_q009_weight_occs.lcip2_cred,
          dacso_q009_weight_occs.noc_cd; "
dbExecute(decimal_con, DACSO_Q009_Weighted_Occs_2D)

