qry99_Completers_agg_byCIP4 <- "
SELECT AgeGroupLookup.age_group,
       t_dacso_data_part_1.prgm_credential_awarded_name,
       Count(*) AS Expr1,
       t_dacso_data_part_1.lcp4_cd,
