	  CONCAT(MAJOR_GROUP_CODE , ' ' , MAJOR_GROUP_ENGLISH_NAME) AS Expr1
	FROM T_PSSM_CRED_RECODE 
	INNER JOIN (tmp_tbl_Q_3d_Occupations_by_LCIP4_CRED_LCP2_Union 
